<script setup>
import{reactive}from'vue';import{register}from'../api';import{ElMessage}from'element-plus';import{useRouter}from'vue-router';const router=useRouter(),form=reactive({username:'',password:'',confirmPassword:'',email:'',displayName:''})
async function submit(){if(form.password.length<6)return ElMessage.warning('密码至少6位');if(form.password!==form.confirmPassword)return ElMessage.warning('两次密码输入不一致');try{const{data}=await register({username:form.username,password:form.password,email:form.email,displayName:form.displayName});localStorage.setItem('craft-user',JSON.stringify(data));localStorage.setItem('craft-token',data.token);ElMessage.success('注册成功');router.push('/')}catch(e){ElMessage.error(e.response?.data?.message||'注册失败')}}
</script><template><div class="login-page"><div class="login-card"><div class="eyebrow">JOIN HANDMADE</div><h2>创建账号</h2><el-form label-position="top"><el-form-item label="昵称"><el-input v-model="form.displayName"/></el-form-item><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password"/></el-form-item><el-form-item label="确认密码"><el-input v-model="form.confirmPassword" type="password"/></el-form-item></el-form><button class="primary-btn" style="width:100%" @click="submit">注册并进入系统</button><p style="text-align:center"><RouterLink to="/login">已有账号，返回登录</RouterLink></p></div></div></template>